package com.hms.services;
import com.hms.departments.*; import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/services") public class ServiceController {private final TenantRepository tenants;private final DepartmentRepository departments;private final HospitalServiceRepository services;public ServiceController(TenantRepository t,DepartmentRepository d,HospitalServiceRepository s){tenants=t;departments=d;services=s;} @GetMapping public List<HospitalService> list(@PathVariable String tenantSlug){return services.findAllByTenantIdOrderByNameAsc(tenant(tenantSlug));} @PostMapping @ResponseStatus(HttpStatus.CREATED) public HospitalService create(@PathVariable String tenantSlug,@Valid @RequestBody CreateServiceRequest r){UUID t=tenant(tenantSlug);if(r.departmentId()!=null){Department d=departments.findById(r.departmentId()).orElseThrow(()->new IllegalArgumentException("Department not found"));if(!d.getTenantId().equals(t))throw new IllegalArgumentException("Department does not belong to hospital");}return services.save(new HospitalService(t,r));} private UUID tenant(String s){return tenants.findBySlug(s).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(s));}}
